function xz_visit_stats_t3_url($view, $filters = array(), $extra = array())
{
    global $zbp;
    $params = array('view' => $view);
    foreach (xz_visit_stats_v2_drilldown_params($filters, $extra) as $key => $value) if ($key !== 'view') $params[$key] = $value;
    return $zbp->host . 'zb_users/plugin/xz_visit_stats/main.php?' . http_build_query($params, '', '&');
}

function xz_visit_stats_t3_date($timestamp)
{
    if ((int) $timestamp <= 0) return '-';
    $date = new DateTime('@' . (int) $timestamp);
    $date->setTimezone(new DateTimeZone(xz_visit_stats_rollup_timezone()));
    return xz_visit_stats_admin_escape($date->format('Y-m-d H:i:s'));
}

function xz_visit_stats_t3_filters($source = null)
{
    $filters = xz_visit_stats_v2_filters($source);
    if ($filters['range'] === 'all') $filters['range'] = '30d';
    return $filters;
}

function xz_visit_stats_t3_status($code)
{
    return '<span class="xz-status ' . xz_visit_stats_admin_status_class($code) . '">' . (int) $code . '</span>';
}

$view = xz_visit_stats_query_text(GetVars('view', 'GET', 'overview'), 16);
$views = array('overview', 'records', 'pages', 'source', 'spider', 'errors', 'realtime', 'ip', 'environment', 'campaign', 'performance', 'settings');
if (!in_array($view, $views, true)) $view = 'overview';
$filters = xz_visit_stats_v3_filters($_GET);
$postResult = array('type' => '', 'message' => '');

if (isset($_SERVER['REQUEST_METHOD']) && $_SERVER['REQUEST_METHOD'] === 'POST' && ($view === 'settings' || xz_visit_stats_query_value($_POST, 't3_action', '') === 'save_filter')) {
    $action = xz_visit_stats_query_text(xz_visit_stats_query_value($_POST, 't3_action', ''), 32);
    if ($action === 'save_filter') {
        if (!CheckCSRFTokenValid('csrfToken', 'post')) {
            $postResult = array('type' => 'error', 'message' => '安全校验失败，请刷新页面后重试。');
        } else {
            $name = xz_visit_stats_query_text(xz_visit_stats_query_value($_POST, 'filter_name', ''), 128);
            $postResult = xz_visit_stats_v3_save_filter($view, $name, $filters) ? array('type' => 'success', 'message' => '常用筛选已保存。') : array('type' => 'error', 'message' => '常用筛选保存失败。');
        }
    } elseif ($action === 'settings') {
        // This T3 form intentionally exposes the common settings only. Preserve
        // legacy per-bot and cleanup flags that are not rendered in this view.
        $currentSettings = xz_visit_stats_settings_values();
        $preserveKeys = isset($_POST['trusted_proxies']) ? array('enabled', 'exclude_admin', 'record_bots', 'record_baiduspider', 'record_googlebot', 'record_bingbot', 'record_other_bots', 'record_referer', 'record_user_agent', 'auto_cleanup', 'beacon_enabled', 'retention_days', 'ip_mode', 'log_alert_count') : array('record_baiduspider', 'record_googlebot', 'record_bingbot', 'record_other_bots', 'auto_cleanup', 'beacon_enabled');
        foreach ($preserveKeys as $preservedKey) {
            if (!array_key_exists($preservedKey, $_POST)) $_POST[$preservedKey] = (string) $currentSettings[$preservedKey];
        }
        $postResult = xz_visit_stats_settings_save($_POST);
    } elseif ($action === 'v3_settings') {
        $currentSettings = xz_visit_stats_settings_values();
        foreach (array('enabled', 'exclude_admin', 'record_bots', 'record_baiduspider', 'record_googlebot', 'record_bingbot', 'record_other_bots', 'record_referer', 'record_user_agent', 'auto_cleanup', 'beacon_enabled', 'retention_days', 'ip_mode', 'log_alert_count') as $preservedKey) {
            if (!array_key_exists($preservedKey, $_POST)) $_POST[$preservedKey] = (string) $currentSettings[$preservedKey];
        }
        $postResult = xz_visit_stats_settings_save($_POST);
    } elseif (!CheckCSRFTokenValid('csrfToken', 'post')) {
        $postResult = array('type' => 'error', 'message' => '安全校验失败，请刷新页面后重试。');
    } elseif ($action === 'rebuild_rollup') {
        $start = xz_visit_stats_query_text(xz_visit_stats_query_value($_POST, 'start_day', ''), 10);
        $end = xz_visit_stats_query_text(xz_visit_stats_query_value($_POST, 'end_day', ''), 10);
        if (preg_match('/^\d{4}-\d{2}-\d{2}$/', $start) !== 1 || preg_match('/^\d{4}-\d{2}-\d{2}$/', $end) !== 1 || $end < $start) {
            $postResult = array('type' => 'error', 'message' => '汇总重建日期范围无效。');
        } else {
            try { $result = xz_visit_stats_rollup_rebuild($start, $end); $postResult = array('type' => 'success', 'message' => '已重建 ' . count($result) . ' 天日汇总。'); }
            catch (Exception $exception) { $postResult = array('type' => 'error', 'message' => '汇总重建失败，详情已记录。'); }
        }
    } elseif ($action === 'pathkey_backfill') {
        try { $result = xz_visit_stats_rollup_backfill_path_keys(200); $postResult = array('type' => 'success', 'message' => 'PathKey 回填处理 ' . (int) $result['processed'] . ' 条，状态：' . ($result['complete'] ? '完成' : '可继续') . '。'); }
        catch (Exception $exception) { $postResult = array('type' => 'error', 'message' => 'PathKey 回填失败，详情已记录。'); }
    } elseif ($action === 'dimension_backfill') {
        try { $result = xz_visit_stats_rollup_backfill_dimensions(200); $postResult = array('type' => 'success', 'message' => '来源/UTM/AI 维度回填处理 ' . (int) $result['processed'] . ' 条。'); }
        catch (Exception $exception) { $postResult = array('type' => 'error', 'message' => '维度回填失败，详情已记录。'); }
    }
}

$data = array();
if (isset($_GET['export']) && $_GET['export'] === 'csv') {
    $exportRange = xz_visit_stats_v2_range($filters);
    if ($filters['range'] === 'all' || ($exportRange['end'] - $exportRange['start']) > 93 * 86400) {
        http_response_code(400);
        header('Content-Type: text/plain; charset=UTF-8');
        echo 'CSV 导出时间范围不得超过 93 天。';
        exit;
    }
    $rows = xz_visit_stats_v3_export_rows($filters, isset($_GET['cursor']) ? $_GET['cursor'] : '', 5000);
    header('Content-Type: text/csv; charset=UTF-8');
    header('Content-Disposition: attachment; filename=xz_visit_stats_export.csv');
    echo "\xEF\xBB\xBF";
    echo "ID,VisitedAt,IP,Type,BotName,Path,Referer,Browser,OS,Device,StatusCode,DurationMs,SourceType,SourceDomain,UtmCampaign\r\n";
    foreach ($rows as $row) {
        $values = array($row['vs_ID'], xz_visit_stats_t3_date($row['vs_VisitedAt']), $row['vs_IP'], (int) $row['vs_IsBot'] === 1 ? 'bot' : 'human', $row['vs_BotName'], $row['vs_Path'], $row['vs_Referer'], $row['vs_Browser'], $row['vs_Os'], $row['vs_Device'], $row['vs_StatusCode'], $row['vs_DurationMs'], isset($row['vs_SourceType']) ? $row['vs_SourceType'] : '', isset($row['vs_SourceDomain']) ? $row['vs_SourceDomain'] : '', isset($row['vs_UtmCampaign']) ? $row['vs_UtmCampaign'] : '');
        echo implode(',', array_map(function ($value) { return '"' . str_replace('"', '""', xz_visit_stats_v3_csv_safe($value)) . '"'; }, $values)) . "\r\n";
    }
    exit;
}
