if ($view === 'spider') { $botFilters = array_merge($filters, array('visit_type' => 'bot')); $data['rows'] = xz_visit_stats_v2_spider_summary($filters, 50); $data['trend'] = xz_visit_stats_v2_trend($botFilters); $data['records'] = xz_visit_stats_v2_records($botFilters, 1, 30); }
