if ($view === 'realtime') { $data['active'] = xz_visit_stats_v3_active_summary(xz_visit_stats_settings_values()['realtime_window']); $data['rows'] = xz_visit_stats_realtime_rows(50); }
if ($view === 'ip') { $data['rows'] = xz_visit_stats_v3_ip_rows($filters, 100); }
